const textOf = (resp) => {
  const c = resp && resp.candidates && resp.candidates[0];
  const parts = (c && c.content && c.content.parts) || [];
  return parts.filter(p => typeof p.text === "string" && !p.thought).map(p => p.text).join("");
};
const parseJson = (raw) => {
  let t = String(raw || "").trim();
  t = t.replace(/^```json/i, "").replace(/^```/, "").replace(/```$/, "").trim();
  const s = t.indexOf("{");
  const e = t.lastIndexOf("}");
  if (s !== -1 && e !== -1) t = t.slice(s, e + 1);
  return JSON.parse(t);
};
const resp = $input.first().json;
const raw = textOf(resp);
if (!raw) {
  const err = resp && resp.error ? JSON.stringify(resp.error) : JSON.stringify(resp).slice(0, 600);
  throw new Error("Agent 1 returned no text. Check the YouTube link is public and not age restricted. Raw response: " + err);
}
const a = parseJson(raw);
const ctx = $("Normalize Input").first().json;
const moments = Array.isArray(a.key_moments) ? a.key_moments : [];
const quotes = Array.isArray(a.quotable_lines) ? a.quotable_lines : [];
const takeaways = Array.isArray(a.audience_takeaways) ? a.audience_takeaways : [];
const data = Array.isArray(a.data_points) ? a.data_points : [];
return [{ json: {
  source_id: ctx.source_id,
  source_url: ctx.source_url,
  creator_name: ctx.creator_name,
  angle_notes: ctx.angle_notes,
  audience: ctx.audience,
  tone_notes: ctx.tone_notes,
  signature_phrases: ctx.signature_phrases,
  banned_words: ctx.banned_words,
  example_post: ctx.example_post,
  created_at: ctx.created_at,
  title: a.title || "Untitled",
  core_thesis: a.core_thesis || "",
  key_moments: moments,
  key_moments_text: moments.map(m => (m.ts || "") + " | " + (m.moment || "") + " | " + (m.why_it_matters || "")).join("\n"),
  quotable_lines: quotes,
  quotable_text: quotes.join("\n"),
  audience_takeaways: takeaways,
  takeaways_text: takeaways.join("\n"),
  contrarian_angle: a.contrarian_angle || "",
  data_points: data,
  data_text: data.join("\n"),
  detected_tone: a.detected_tone || ""
} }];

const textOf = (resp) => {
  const c = resp && resp.candidates && resp.candidates[0];
  const parts = (c && c.content && c.content.parts) || [];
  return parts.filter(p => typeof p.text === "string" && !p.thought).map(p => p.text).join("");
};
const parseJson = (raw) => {
  let t = String(raw || "").trim();
  t = t.replace(/^```json/i, "").replace(/^```/, "").replace(/```$/, "").trim();
  const s = t.indexOf("{");
  const e = t.lastIndexOf("}");
  if (s !== -1 && e !== -1) t = t.slice(s, e + 1);
  try { return JSON.parse(t); } catch (err) { return null; }
};
const grab = (nodeName) => {
  try { return parseJson(textOf($(nodeName).first().json)); } catch (err) { return null; }
};
const src = $("Parse Source Analysis").first().json;
const stamp = $now.toFormat("yyyyMMddHHmmss");
const created = $now.toFormat("yyyy-MM-dd HH:mm");
const rows = [];
const failures = [];
let n = 0;
const push = (platform, format, hook, body, hashtags, cta, ts) => {
  n += 1;
  rows.push({
    content_id: "CM" + stamp + "-" + String(n).padStart(2, "0"),
    source_id: src.source_id,
    source_title: src.title,
    platform: platform,
    format: format,
    hook: String(hook == null ? "" : hook).slice(0, 4000),
    body: String(body == null ? "" : body).slice(0, 40000),
    hashtags: String(hashtags == null ? "" : hashtags),
    cta: String(cta == null ? "" : cta),
    timestamp_ref: String(ts == null ? "" : ts),
    status: "draft",
    scheduled_for: "",
    published_at: "",
    created_at: created
  });
};
const shorts = grab("Agent 2 - Short Form Scripts");
if (!shorts) failures.push("Agent 2");
((shorts && shorts.scripts) || []).slice(0, 3).forEach(s => {
  push("reels", "short_script", s.hook, String(s.script || "") + "\n\nON SCREEN TEXT: " + (s.on_screen_text || ""), "", s.cta, s.source_timestamp);
});
const li = grab("Agent 3 - LinkedIn Writer");
if (!li) failures.push("Agent 3");
((li && li.posts) || []).slice(0, 5).forEach(p => {
  push("linkedin", p.format || "post", p.hook, p.body, p.hashtags, p.cta, p.source_timestamp);
});
const xp = grab("Agent 4 - X Writer");
if (!xp) failures.push("Agent 4");
((xp && xp.posts) || []).slice(0, 9).forEach(p => {
  push("x", p.format || "single", p.hook, p.body, p.hashtags, p.cta, p.source_timestamp);
});
const nl = grab("Agent 5 - Newsletter Writer");
if (!nl) failures.push("Agent 5");
if (nl && nl.newsletter) {
  const w = nl.newsletter;
  push("newsletter", "issue", w.subject_line, (w.preview_text ? "PREVIEW: " + w.preview_text + "\n\n" : "") + (w.body || ""), "", w.cta, w.source_timestamp);
}
const qc = grab("Agent 6 - Quote Card Designer");
if (!qc) failures.push("Agent 6");
((qc && qc.cards) || []).slice(0, 3).forEach(c => {
  push("quote_card", "graphic", c.quote, "CAPTION: " + (c.caption || "") + "\n\nDESIGN: " + (c.design_direction || "") + "\n\nALT TEXT: " + (c.alt_text || ""), "", c.attribution || src.creator_name, c.source_timestamp);
});
if (rows.length === 0) {
  throw new Error("No content rows produced. Agents that failed to return parsable JSON: " + failures.join(", "));
}
return rows.map(r => ({ json: r }));

const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const nl2br = (s) => esc(s).replace(/\n/g,'<br>');

const rows = $("Build 21 Content Rows").all().map(i => i.json);
const src = $("Build Source Row").first().json;

const CREAM='#F7F8F4';
const WHITE='#FFFFFF';
const GREEN='#267A4B';
const DARK_GREEN='#155B38';
const LIME='#C8F135';
const YELLOW='#F4D35E';
const SOFT_GREEN='#E8F3EA';
const SOFT_YELLOW='#FFF7D6';
const SOFT_BLUE='#EAF3F8';
const INK='#24332A';
const GREY='#707A73';
const BORDER='#DDE6DE';

const platMeta = {
  reels:      { label: 'Reels and Shorts', accent: '#E8F3EA' },
  linkedin:   { label: 'LinkedIn',         accent: '#EAF3F8' },
  x:          { label: 'X',                accent: '#F0F0F0' },
  newsletter: { label: 'Newsletter',       accent: '#FFF7D6' },
  quote_card: { label: 'Quote Cards',      accent: '#F3EAF8' }
};

const order = ['reels','linkedin','x','newsletter','quote_card'];

const groups = {};
rows.forEach(r => {
  const p=(r.platform||'other').toLowerCase();
  (groups[p]=groups[p]||[]).push(r);
});

let pieceHtml = '';

order.forEach(pk => {
  const list = groups[pk];
  if (!list || !list.length) return;

  const meta = platMeta[pk] || { label: pk, accent: SOFT_GREEN };

  pieceHtml += '<tr><td style="padding:28px 26px 10px 26px;">'
    + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
    + '<td style="font-family:Georgia,serif;font-size:20px;font-weight:bold;color:'+INK+';">'
    + esc(meta.label)
    + '</td>'
    + '<td align="right">'
    + '<span style="background:'+meta.accent+';color:'+GREEN+';font-family:Calibri,Arial,sans-serif;font-size:12px;font-weight:bold;padding:5px 12px;border-radius:20px;">'
    + list.length+' '+(list.length===1?'piece':'pieces')
    + '</span>'
    + '</td>'
    + '</tr></table></td></tr>';

  list.forEach((r, idx) => {

    const badge =
      esc((r.format||'').toUpperCase()) +
      (r.timestamp_ref ? '  &middot;  '+esc(r.timestamp_ref) : '');

    let bodyBlock = '';

    if (pk === 'newsletter') {

      let b = String(r.body||'');
      let preview = '';

      const m = b.match(/^PREVIEW:\s*(.*?)\n\n([\s\S]*)$/);

      if (m) {
        preview = m[1];
        b = m[2];
      }

      bodyBlock =
        (preview
          ? '<div style="font-size:12px;color:'+GREY+';font-style:italic;margin-bottom:10px;padding:9px 11px;background:'+SOFT_YELLOW+';border-radius:6px;">'
          + 'Preview: '+esc(preview)
          + '</div>'
          : '')
        +
        '<div style="font-size:14px;color:'+INK+';line-height:1.65;">'
        + b
        + '</div>';

    } else {

      bodyBlock =
        '<div style="font-size:14px;color:'+INK+';line-height:1.65;">'
        + nl2br(r.body)
        + '</div>';

    }

    const hashtags = r.hashtags
      ? '<div style="font-size:13px;color:'+GREEN+';margin-top:12px;font-weight:bold;">'
        + esc(r.hashtags)
        + '</div>'
      : '';

    const cta = r.cta
      ? '<div style="font-size:13px;color:'+GREY+';margin-top:10px;padding-top:10px;border-top:1px solid '+BORDER+';">'
        + '<strong style="color:'+GREEN+';">CTA:</strong> '
        + esc(r.cta)
        + '</div>'
      : '';

    pieceHtml +=
      '<tr><td style="padding:8px 26px;">'
      + '<table width="100%" cellpadding="0" cellspacing="0" style="background:'+WHITE+';border:1px solid '+BORDER+';border-radius:12px;">'
      + '<tr><td style="padding:19px 20px;border-left:5px solid '+LIME+';">'

      + '<div style="font-family:Calibri,Arial,sans-serif;font-size:10px;font-weight:bold;color:'+GREY+';letter-spacing:1.2px;margin-bottom:9px;">'
      + badge
      + '</div>'

      + '<div style="font-family:Georgia,serif;font-size:16px;font-weight:bold;color:'+INK+';margin-bottom:11px;line-height:1.4;">'
      + nl2br(r.hook)
      + '</div>'

      + bodyBlock
      + hashtags
      + cta

      + '</td></tr></table>'
      + '</td></tr>';
  });
});

const pieces = rows.length;

const html = ''

+ '<div style="background:'+CREAM+';padding:24px 0;margin:0;">'

+ '<table width="100%" cellpadding="0" cellspacing="0" style="max-width:680px;margin:0 auto;background:'+CREAM+';font-family:Calibri,Arial,sans-serif;">'


// HEADER
+ '<tr><td style="background:linear-gradient(135deg,'+GREEN+','+DARK_GREEN+');padding:34px 28px;border-radius:14px;">'

+ '<div style="color:'+LIME+';font-size:11px;font-weight:bold;letter-spacing:3px;">'
+ 'CONTENT INTELLIGENCE'
+ '</div>'

+ '<div style="color:'+WHITE+';font-family:Georgia,serif;font-size:30px;font-weight:bold;margin-top:9px;line-height:1.2;">'
+ 'Your Content Pack is ready'
+ '</div>'

+ '<div style="color:#DCEDE2;font-size:15px;margin-top:9px;line-height:1.5;">'
+ pieces+' pieces, written in your voice, from one source.'
+ '</div>'

+ '<div style="width:52px;height:5px;background:'+YELLOW+';margin-top:18px;border-radius:5px;"></div>'

+ '</td></tr>'


// SOURCE
+ '<tr><td style="padding:28px 26px 8px 26px;">'

+ '<div style="font-family:Georgia,serif;font-size:19px;font-weight:bold;color:'+INK+';">'
+ esc(src.source_title)
+ '</div>'

+ '<div style="font-size:12px;color:'+GREY+';margin-top:5px;word-break:break-all;">'
+ esc(src.source_url)
+ '</div>'

+ '<div style="background:'+WHITE+';border:1px solid '+BORDER+';border-radius:11px;padding:17px 18px;margin-top:15px;">'

+ '<span style="font-size:11px;font-weight:bold;color:'+GREEN+';letter-spacing:1px;">'
+ 'CORE THESIS'
+ '</span>'

+ '<div style="font-size:14px;color:'+INK+';line-height:1.6;margin-top:7px;">'
+ esc(src.core_thesis)
+ '</div>'

+ '</div>'

+ '</td></tr>'


// STATS
+ '<tr><td style="padding:16px 26px 5px 26px;">'

+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'

+ '<td align="center" style="background:'+GREEN+';border-radius:9px;padding:16px 6px;">'
+ '<div style="color:'+LIME+';font-family:Georgia,serif;font-size:25px;font-weight:bold;">'
+ pieces
+ '</div>'
+ '<div style="color:#DCEDE2;font-size:11px;margin-top:2px;">total pieces</div>'
+ '</td>'

+ '<td width="10"></td>'

+ '<td align="center" style="background:'+SOFT_BLUE+';border:1px solid #D5E5ED;border-radius:9px;padding:16px 6px;">'
+ '<div style="color:'+GREEN+';font-family:Georgia,serif;font-size:25px;font-weight:bold;">5</div>'
+ '<div style="color:'+GREY+';font-size:11px;margin-top:2px;">platforms</div>'
+ '</td>'

+ '<td width="10"></td>'

+ '<td align="center" style="background:'+SOFT_YELLOW+';border:1px solid #F0E5B8;border-radius:9px;padding:16px 6px;">'
+ '<div style="color:'+DARK_GREEN+';font-family:Georgia,serif;font-size:25px;font-weight:bold;">Rs 0</div>'
+ '<div style="color:'+GREY+';font-size:11px;margin-top:2px;">cost</div>'
+ '</td>'

+ '</tr></table></td></tr>'


// CONTENT
+ pieceHtml


// NEXT STEP
+ '<tr><td style="padding:30px 26px;">'

+ '<table width="100%" cellpadding="0" cellspacing="0" style="background:'+SOFT_GREEN+';border:1px solid #D4E5D7;border-radius:12px;">'

+ '<tr><td style="padding:23px 22px;">'

+ '<div style="color:'+DARK_GREEN+';font-family:Georgia,serif;font-size:18px;font-weight:bold;margin-bottom:8px;">'
+ 'Next step'
+ '</div>'

+ '<div style="color:'+INK+';font-size:14px;line-height:1.6;margin-bottom:17px;">'
+ 'Open the Content Library, read each piece, set the ones you like to approved and add a scheduled_for time. Workflow 2 polishes, brand-checks and delivers each one at its slot.'
+ '</div>'

+ '<a href="https://docs.google.com/spreadsheets/d/142dfvdDw_Se5hDsnsX_FdyKXTkVflqYuOYSM6Qm8F3g/edit#gid=612816458" style="display:inline-block;background:'+GREEN+';color:'+WHITE+';padding:12px 24px;text-decoration:none;font-weight:bold;font-size:14px;border-radius:6px;">'
+ 'Open Content Library →'
+ '</a>'

+ '</td></tr></table></td></tr>'


// FOOTER
+ '<tr><td style="padding:5px 26px 25px 26px;">'

+ '<div style="font-size:11px;color:'+GREY+';">'
+ 'Processed '+esc(src.processed_at)
+ ' &nbsp;&middot;&nbsp; Build. Automate. Scale. &nbsp;&middot;&nbsp; Team HOI'
+ '</div>'

+ '</td></tr>'

+ '</table></div>';

return [{
  json: {
    digest_html: html,
    pieces: pieces,
    source_title: src.source_title,
    processed_at: src.processed_at
  }
}];

