{
  "title": "How to Build a One Person AI Business (Using Claude Code)",
  "core_thesis": "You can build a profitable one-person AI consulting business by focusing on solving specific business constraints rather than selling AI features.",
  "key_moments": [
    {
      "ts": "00:36",
      "moment": "The shift from 'AI builder' to 'AI partner'.",
